*/
scwin.search = function (orderBy) {
    /* sdd-asis-lifecycle:begin fn_Search — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    /* empty */
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.onEnter
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.onEnter = function () {
    /* sdd-asis-lifecycle:begin onEnter — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    /* empty */
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.content
 * @author Inswave
 * @date 2026. 09. 29
 * @param helpClssId
 * @returns
 * @hidden N
*/
scwin.content = async function (helpClssId) {
    /* sdd-asis-lifecycle:begin fn_Content — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const _url = "/filing/systemInfo.do?method=findSystemInfo&helpClssId=" + helpClssId;
    const _props = "toolbar=no,menubar=no,scrollbars=yes,status=yes,resizable=yes,width=700,height=300";
    await $c.win.openPopup((function (__u) { var __s = String(__u == null ? "" : __u); if (!/\.xml(\?|#|$)/.test(__s)) { throw { bizMessage: "이 화면의 이동 목적지를 아직 정하지 못했습니다(전환 미완) — " + __s, unresolved: "nav:" + __s }; } return __u; })(_url), { id: "sysInfoPop", popupName: "sysInfoPop", width: "700", height: "630" }, {});
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.addHelpClass
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.addHelpClass = async function () {
    /* sdd-asis-lifecycle:begin fn_AddHelpClass — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const _url = "/filing/updateSystemInfo.do?method=prepareUpdateHelpClass" + "&mode=create";
    await $c.win.openPopup((function (__u) { var __s = String(__u == null ? "" : __u); if (!/\.xml(\?|#|$)/.test(__s)) { throw { bizMessage: "이 화면의 이동 목적지를 아직 정하지 못했습니다(전환 미완) — " + __s, unresolved: "nav:" + __s }; } return __u; })(_url), { id: "helpClassPop", popupName: "helpClassPop" }, {});
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.modHelpClass
 * @author Inswave
 * @date 2026. 09. 29
 * @param helpClssId
 * @returns
 * @hidden N
*/
scwin.modHelpClass = async function (helpClssId) {
    /* sdd-asis-lifecycle:begin fn_ModHelpClass — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const _url = "/filing/updateSystemInfo.do?method=prepareUpdateHelpClass" + "&helpClssId=" + helpClssId + "&mode=update";
    await $c.win.openPopup((function (__u) { var __s = String(__u == null ? "" : __u); if (!/\.xml(\?|#|$)/.test(__s)) { throw { bizMessage: "이 화면의 이동 목적지를 아직 정하지 못했습니다(전환 미완) — " + __s, unresolved: "nav:" + __s }; } return __u; })(_url), { id: "helpClassPop", popupName: "helpClassPop", width: "610", height: "260" }, {});
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.deleteListXhrReq
 * @author Inswave
 * @date 2026. 09. 29
 * @param helpClssId helpClssNm
 * @returns
 * @hidden N
*/
scwin.deleteListXhrReq = async function (helpClssId, helpClssNm) {
    /* sdd-asis-lifecycle:begin fn_Delete — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const _confirm = await $c.win.confirm("도움말분류 '" + helpClssNm + "'를\n삭제하시겠습니까?");
    if (!_confirm) {
        return;
    }
    $c.util.getComponent('dma_ListXhrReq').set('helpClssId', helpClssId);
    scwin.form_listForm.action = "/filing/systemInfo.do";
    $c.util.getComponent('dma_ListXhrReq').set('method', "deleteHelpClass");
    $c.util.getComponent('txt_sysListDiv').setValue(await scwin.tx_fn_Delete_xhr());
    /* sdd-asis-lifecycle:end */
};
